import{_ as e,c as t,o as a,ag as i}from"./chunks/framework.Bzez9NG9.js";const o="/space/img/settings-connections-detect.png",s="/space/img/settings-connections-create.png",c="/space/img/connection-access.png",r="/space/img/connection-access-edit.png",b=JSON.parse('{"title":"IBM Planning Analytics","description":"Configure IBM Planning Analytics connections in SPACE, including user authentication, job credentials, testing, server detection, and connection access.","frontmatter":{"title":"IBM Planning Analytics","description":"Configure IBM Planning Analytics connections in SPACE, including user authentication, job credentials, testing, server detection, and connection access.","keywords":["IBM Planning Analytics","TM1","TM1 REST API","connections","SSO","OAuth","CAM","Basic authentication","API key","job credentials","PAW session","connection access"],"outline":"deep"},"headers":[],"relativePath":"doc/configuration/connections/ibm-planning-analytics.md","filePath":"doc/configuration/connections/ibm-planning-analytics.md"}'),l={name:"doc/configuration/connections/ibm-planning-analytics.md"};function d(p,n,h,g,u,m){return a(),t("div",null,n[0]||(n[0]=[i('<h1 id="ibm-planning-analytics" tabindex="-1">IBM Planning Analytics <a class="header-anchor" href="#ibm-planning-analytics" aria-label="Permalink to &quot;IBM Planning Analytics&quot;">​</a></h1><p>IBM Planning Analytics connections allow SPACE to work with TM1 environments across IBM Planning Analytics Cloud, Planning Analytics Local, and IBM Planning Analytics as a Service.</p><p>Each connection defines the TM1 REST API endpoint and the authentication used for interactive users and, when required, non-interactive jobs and Python execution.</p><h2 id="detecting-servers" tabindex="-1">Detecting servers <a class="header-anchor" href="#detecting-servers" aria-label="Permalink to &quot;Detecting servers&quot;">​</a></h2><p>The <strong>Detect</strong> option is available for <strong>IBM Planning Analytics on Cloud</strong> and <strong>IBM Planning Analytics as a Service</strong> connections.</p><p>Click <strong>Detect</strong> to discover Planning Analytics servers that are available to the configured cloud environment, then select the required result to add it as a SPACE connection.</p><p><img src="'+o+'" alt="Found connections modal" data-zoomable=""></p><p>The <strong>Detect</strong> option is not available for <strong>IBM Planning Analytics Local</strong>. Local connections must be configured manually using the TM1 REST API endpoint and the appropriate authentication settings.</p><h2 id="creating-or-editing-a-connection" tabindex="-1">Creating or editing a connection <a class="header-anchor" href="#creating-or-editing-a-connection" aria-label="Permalink to &quot;Creating or editing a connection&quot;">​</a></h2><p>Choose <strong>New connection</strong>, or open an existing IBM Planning Analytics connection, to configure it.</p><p><img src="'+s+'" alt="New connection modal" data-zoomable=""></p><p>Provide:</p><ul><li><strong>Connection Type</strong> – IBM Planning Analytics.</li><li><strong>Environment Type</strong> – descriptive label such as Production, UAT, QA, Development, or Sandbox.</li><li><strong>Name</strong> – friendly name shown throughout SPACE.</li><li><strong>Connection URL</strong> – TM1 REST API endpoint for the Planning Analytics environment.</li></ul><h3 id="connection-url-formats" tabindex="-1">Connection URL formats <a class="header-anchor" href="#connection-url-formats" aria-label="Permalink to &quot;Connection URL formats&quot;">​</a></h3><p>The TM1 REST API URL format depends on the IBM Planning Analytics deployment type.</p><h4 id="ibm-planning-analytics-local" tabindex="-1">IBM Planning Analytics Local <a class="header-anchor" href="#ibm-planning-analytics-local" aria-label="Permalink to &quot;IBM Planning Analytics Local&quot;">​</a></h4><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://TM1_HOST:TM1_PORT_NUMBER_/api/v1/</span></span></code></pre></div><ul><li><code>TM1_HOST</code> is the TM1 server host.</li><li><code>TM1_PORT_NUMBER</code> is the <code>HTTPPortNumber</code> configured in the TM1 <code>tm1s.cfg</code> file.</li></ul><h4 id="ibm-planning-analytics-cloud" tabindex="-1">IBM Planning Analytics Cloud <a class="header-anchor" href="#ibm-planning-analytics-cloud" aria-label="Permalink to &quot;IBM Planning Analytics Cloud&quot;">​</a></h4><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://COMPANY.planning-analytics.cloud.ibm.com/tm1/api/TM1_SERVER_NAME/api/v1/</span></span></code></pre></div><p>Replace <code>COMPANY</code> with the Planning Analytics Cloud hostname and <code>TM1_SERVER_NAME</code> with the TM1 server name.</p><p><code>TM1_SERVER_NAME</code> is case-sensitive.</p><h4 id="ibm-planning-analytics-as-a-service" tabindex="-1">IBM Planning Analytics as a Service <a class="header-anchor" href="#ibm-planning-analytics-as-a-service" aria-label="Permalink to &quot;IBM Planning Analytics as a Service&quot;">​</a></h4><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://AWS_REGION.planninganalytics.saas.ibm.com/api/TENANT_ID/v0/tm1/TM1_SERVER_NAME/api/v1/</span></span></code></pre></div><p>Replace:</p><ul><li><code>AWS_REGION</code> with the IBM Planning Analytics as a Service region.</li><li><code>TENANT_ID</code> with the tenant identifier.</li><li><code>TM1_SERVER_NAME</code> with the TM1 server name.</li></ul><p><code>TM1_SERVER_NAME</code> is case-sensitive.</p><p>The authentication fields shown in the form depend on the selected authentication method.</p><p>Use <strong>Test connection</strong> to validate the configuration before saving.</p><h2 id="user-credentials" tabindex="-1">User credentials <a class="header-anchor" href="#user-credentials" aria-label="Permalink to &quot;User credentials&quot;">​</a></h2><p><strong>User credentials</strong> define how interactive users authenticate when SPACE accesses the Planning Analytics connection.</p><p>SPACE supports:</p><table tabindex="0"><thead><tr><th>Authentication</th><th>Configuration</th></tr></thead><tbody><tr><td><strong>IBM Planning Analytics Cloud (SSO)</strong></td><td>Client ID and Client Secret. Can reuse the active PAW session when available.</td></tr><tr><td><strong>IBM Planning Analytics Cloud (Non-Interactive)</strong></td><td>Namespace, Username, and Password.</td></tr><tr><td><strong>IBM Planning Analytics Local (SSO)</strong></td><td>Cognos Gateway URL and Proxy URL.</td></tr><tr><td><strong>IBM Planning Analytics Local (CAM)</strong></td><td>Namespace, Username, and Password.</td></tr><tr><td><strong>IBM Planning Analytics Local (Basic)</strong></td><td>Username and Password.</td></tr><tr><td><strong>IBM Planning Analytics as a Service (API Key)</strong></td><td>API Key.</td></tr></tbody></table><h3 id="ibm-planning-analytics-cloud-sso" tabindex="-1">IBM Planning Analytics Cloud SSO <a class="header-anchor" href="#ibm-planning-analytics-cloud-sso" aria-label="Permalink to &quot;IBM Planning Analytics Cloud SSO&quot;">​</a></h3><p>For <strong>IBM Planning Analytics Cloud (SSO)</strong>, configure the OAuth Client ID and Client Secret for an authorized application.</p><p>Follow IBM&#39;s <a href="https://www.ibm.com/docs/en/planning-analytics/2.1.0?topic=oauth-configuring-authorized-applications" target="_blank" rel="noreferrer">Configuring authorized applications (OAuth)</a> documentation to create the authorized application and generate the OAuth credentials.</p><h3 id="reuse-paw-session-when-available" tabindex="-1">Reuse PAW session when available <a class="header-anchor" href="#reuse-paw-session-when-available" aria-label="Permalink to &quot;Reuse PAW session when available&quot;">​</a></h3><p>For <strong>IBM Planning Analytics Cloud (SSO)</strong>, enable <strong>Reuse PAW session when available</strong> to allow SPACE to reuse the user&#39;s active IBM Planning Analytics Workspace session when SPACE is running through the PAW extension.</p><p>This avoids requiring the user to authenticate again when an appropriate PAW session is already available.</p><h3 id="prompt-for-credentials" tabindex="-1">Prompt for credentials <a class="header-anchor" href="#prompt-for-credentials" aria-label="Permalink to &quot;Prompt for credentials&quot;">​</a></h3><p>Authentication methods that use username/password or API-key credentials can support <strong>Prompt for credentials</strong>.</p><p>When enabled, SPACE asks each user to provide their own credentials instead of reusing credentials stored with the connection.</p><p>This is useful when users should authenticate to Planning Analytics individually but the connection does not use SSO.</p><h2 id="job-credentials" tabindex="-1">Job credentials <a class="header-anchor" href="#job-credentials" aria-label="Permalink to &quot;Job credentials&quot;">​</a></h2><p><strong>Job credentials</strong> are separate from interactive user authentication. They provide stored credentials for non-interactive execution that cannot depend on a user&#39;s active session.</p><p>They are used by supported SPACE jobs and Python scripts that need to access the Planning Analytics connection automatically.</p><p>Because job execution is non-interactive, the available authentication methods are:</p><table tabindex="0"><thead><tr><th>Authentication</th><th>Configuration</th></tr></thead><tbody><tr><td><strong>IBM Planning Analytics Cloud (Non-Interactive)</strong></td><td>Namespace, Username, and Password.</td></tr><tr><td><strong>IBM Planning Analytics Local (CAM)</strong></td><td>Namespace, Username, and Password.</td></tr><tr><td><strong>IBM Planning Analytics Local (Basic)</strong></td><td>Username and Password.</td></tr><tr><td><strong>IBM Planning Analytics as a Service (API Key)</strong></td><td>API Key.</td></tr></tbody></table><p>Use credentials appropriate for the automated workload rather than relying on an interactive user&#39;s session.</p><p>See <a href="./../jobs.html">Jobs</a> for scheduled execution and <a href="./../../python/">Python</a> for Python workflows.</p><h2 id="connection-access" tabindex="-1">Connection access <a class="header-anchor" href="#connection-access" aria-label="Permalink to &quot;Connection access&quot;">​</a></h2><p>Connection access maps SPACE security roles to capabilities for a specific IBM Planning Analytics connection.</p><p>This allows the same SPACE role to have different permissions on different Planning Analytics environments. For example, a role can have read-only access to a production connection while receiving model-development capabilities on a development connection.</p><p>Open <strong>Access</strong> for a selected connection to view the role mappings.</p><p><img src="'+c+'" alt="Connection access" data-zoomable=""></p><p>Create a role mapping with <strong>New access</strong>, or open an existing role to change its capabilities.</p><p><img src="'+r+'" alt="Edit connection access" data-zoomable=""></p><p>The available IBM Planning Analytics capabilities are:</p><table tabindex="0"><thead><tr><th>Capability</th><th>Description</th></tr></thead><tbody><tr><td><code>READ</code></td><td>Allows read-only access and general usage of the connection.</td></tr><tr><td><code>MODEL_DOCUMENTATION</code></td><td>View Model documentation.</td></tr><tr><td><code>MODEL_SEARCH</code></td><td>Use Model search.</td></tr><tr><td><code>MODEL_TOOLS</code></td><td>Use model tools.</td></tr><tr><td><code>MODEL_WRITE</code></td><td>Create and modify TM1 model objects.</td></tr><tr><td><code>MODEL_DEPLOY</code></td><td>Use the connection as a deployment target in Model lifecycle.</td></tr><tr><td><code>AUDIT_LOG</code></td><td>View the Audit log.</td></tr><tr><td><code>SERVER_LOG</code></td><td>View the Server log.</td></tr><tr><td><code>TRANSACTION_LOG</code></td><td>View the Transaction log.</td></tr></tbody></table><p>Grant only the capabilities required by the role.</p><p>SPACE connection capabilities control access to SPACE functionality for the connection. IBM Planning Analytics authentication and native TM1 security continue to apply when SPACE accesses the underlying Planning Analytics environment.</p>',61)]))}const A=e(l,[["render",d]]);export{b as __pageData,A as default};
